-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): rodpump capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- BEGINNER
--   Fields read with the switch on: unit_stroke_in, pump_rated_displacement_bpd.
--   The Unit and Loads panels round the stroke and the rated displacement to 1
--   decimal against tolerances of 2.5e-5 and 7.3e-5.
--   APPENDED: Read the figures in the Rod Pump Design Studio with its Full
--   precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/rodpump.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- rodpump / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'rodpump' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w3 rodpump refused: rodpump/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'f09343bae3c9691c79eb2815b5258024' and fields = '[{"key": "string_kr_lb_per_in", "tol": 0.000048, "unit": "lb/in", "label": "Rod string spring rate", "expected": 237.9571451078754}, {"key": "string_buoyed_weight_lb", "tol": 0.0024, "unit": "lbf", "label": "Buoyed string weight", "expected": 11903.896611464968}, {"key": "string_natural_freq_spm", "tol": 0.0000094, "unit": "spm", "label": "Natural frequency", "expected": 46.52548077425118}, {"key": "unit_stroke_in", "tol": 0.000025, "unit": "in", "label": "Surface stroke", "expected": 121.38337590532858}, {"key": "pump_fluid_load_lb", "tol": 0.00088, "unit": "lbf", "label": "Fluid load", "expected": 4364.850293081319}, {"key": "pump_rated_displacement_bpd", "tol": 0.000073, "unit": "bbl/d", "label": "Rated displacement", "expected": 362.9423814326748}]'::jsonb then 'old'
              when md5(prompt) = 'b941e28c43d75f9458638181017ed833' and fields = '[{"key": "string_kr_lb_per_in", "tol": 0.000048, "unit": "lb/in", "label": "Rod string spring rate", "expected": 237.9571451078754}, {"key": "string_buoyed_weight_lb", "tol": 0.0024, "unit": "lbf", "label": "Buoyed string weight", "expected": 11903.896611464968}, {"key": "string_natural_freq_spm", "tol": 0.0000094, "unit": "spm", "label": "Natural frequency", "expected": 46.52548077425118}, {"key": "unit_stroke_in", "tol": 0.000025, "unit": "in", "label": "Surface stroke", "expected": 121.38337590532858}, {"key": "pump_fluid_load_lb", "tol": 0.00088, "unit": "lbf", "label": "Fluid load", "expected": 4364.850293081319}, {"key": "pump_rated_displacement_bpd", "tol": 0.000073, "unit": "bbl/d", "label": "Rated displacement", "expected": 362.9423814326748}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'rodpump' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w3 rodpump refused: rodpump/beginner matches neither its post-W1 form (prompt md5 f09343bae3c9691c79eb2815b5258024) nor its W3 form (prompt md5 b941e28c43d75f9458638181017ed833), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' then
    raise notice 'w3 rodpump: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 rodpump refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Six values for OBAGI-27 that are settled BEFORE a single time step is taken, and there is deliberately no card in this question. THE STRING is a three-way taper hanging 6085 ft: 1825 ft of 1 in rod at the top, then 2140 ft of 7/8 in, then 2120 ft of 3/4 in at the bottom, all API GRADE D, hanging in a fluid of SPECIFIC GRAVITY 0.94. THE UNIT is conventional, and these are its own drawing dimensions: a walking beam with a 118.4 in FRONT arm from the saddle bearing to the polished rod and a 71.6 in REAR arm from the saddle bearing to the equalizer, a 92.5 in pitman, a crank pivot 104.3 in behind and 66.9 in below the saddle bearing, and a 33.7 in crank radius. Close the linkage at 720 CRANK ANGLES. THE PUMP has a 1.5 IN PLUNGER, an intake pressure of 210 PSIA and a discharge pressure of 2680 PSIA, and the unit runs at 11.4 SPM. What the barrel actually fills, how efficient the pump is and how heavily the string is damped are the Professional tier''s to work out and are not needed here. Report: (1) the SPRING RATE of the string; (2) its BUOYED WEIGHT; (3) its NATURAL FREQUENCY; (4) the SURFACE STROKE the linkage gives; (5) the FLUID LOAD on the plunger; and (6) the RATED DISPLACEMENT. Traps. Field 2 is not the weight in air. The string weighs 13,523.24 lb dry, and the buoyancy factor comes from the 0.94 fluid rather than from water, so a design worked in water is wrong in the third figure and wrong in the same direction on every load that follows it. Field 3 has TWO candidate answers and only one is asked for. A uniform bar of the same length has a fundamental of its own, and a taper raises it by a taper factor; report the TAPERED string''s note, which the string explorer''s typed string view reads from the three sections stated above. Field 4 has the same shape of trap from the other direction: the textbook shorthand of twice the crank radius times the front arm over the rear arm gives 111.45474860 in on this unit, and the four-bar closed properly gives something 9.93 in longer, because a pitman of finite length is not a rigid link of zero mass and the shorthand is a small-angle approximation nobody states. Field 5 is a DIFFERENTIAL times an AREA and nothing else: no depth, no specific gravity, no fillage. Field 6 is a RATING and not a production forecast: it is the pump constant times the plunger diameter SQUARED times the SURFACE stroke times the speed, with no barrel fillage and no pump efficiency in it, so it is the largest number this well can be made to produce and not a number it will. Free checks: field 2 divided by the 13,523.24 lb weight in air must equal one less the fluid''s own weight over steel''s, and must therefore be the SAME buoyancy factor for every taper hung in this fluid. Field 3 must EXCEED the fundamental of a uniform bar of the same length, by exactly the taper factor, because stiffening the top of a bar can only raise its note. Field 4 must EXCEED 111.45474860 in, and if your linkage returns something below it you have closed the four-bar on the wrong branch. Field 5 divided by the plunger area must return 2470 psi exactly, the differential and nothing else. Field 6 divided by field 4, then by 11.4, then by 1.5 squared, must return the package''s own pump constant of 0.11657115597735782 bbl per day per in2 per in per spm, which is built from 42 gallons of 231 in3 rather than stored, so the same division done against a stored constant off a chart will miss in the sixth figure. And the 11.4 spm the unit runs at must sit WELL BELOW field 3, since a beam pump run near the string''s own note is a different design problem from this one. Read the figures in the Rod Pump Design Studio with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'rodpump' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 rodpump refused: rodpump/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'b941e28c43d75f9458638181017ed833' and fields = '[{"key": "string_kr_lb_per_in", "tol": 0.000048, "unit": "lb/in", "label": "Rod string spring rate", "expected": 237.9571451078754}, {"key": "string_buoyed_weight_lb", "tol": 0.0024, "unit": "lbf", "label": "Buoyed string weight", "expected": 11903.896611464968}, {"key": "string_natural_freq_spm", "tol": 0.0000094, "unit": "spm", "label": "Natural frequency", "expected": 46.52548077425118}, {"key": "unit_stroke_in", "tol": 0.000025, "unit": "in", "label": "Surface stroke", "expected": 121.38337590532858}, {"key": "pump_fluid_load_lb", "tol": 0.00088, "unit": "lbf", "label": "Fluid load", "expected": 4364.850293081319}, {"key": "pump_rated_displacement_bpd", "tol": 0.000073, "unit": "bbl/d", "label": "Rated displacement", "expected": 362.9423814326748}]'::jsonb) from public.academy_capstones where app_slug = 'rodpump' and tier = 'beginner' and active) is not true then
    raise exception 'w3 rodpump refused: rodpump/beginner does not read back as its W3 form';
  end if;

  raise notice 'w3 rodpump: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
